extension SpreadSlot: Equatable, Hashable {
    public static func == (lhs: SpreadSlot, rhs: SpreadSlot) -> Bool {
        if lhs.slotId != rhs.slotId {
            return false
        }
        if lhs.titleEn != rhs.titleEn {
            return false
        }
        if lhs.titleZh != rhs.titleZh {
            return false
        }
        if lhs.meaningPrompt != rhs.meaningPrompt {
            return false
        }
        if lhs.x != rhs.x {
            return false
        }
        if lhs.y != rhs.y {
            return false
        }
        if lhs.rotationDeg != rhs.rotationDeg {
            return false
        }
        if lhs.zIndex != rhs.zIndex {
            return false
        }
        if lhs.constraint != rhs.constraint {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(slotId)
        hasher.combine(titleEn)
        hasher.combine(titleZh)
        hasher.combine(meaningPrompt)
        hasher.combine(x)
        hasher.combine(y)
        hasher.combine(rotationDeg)
        hasher.combine(zIndex)
        hasher.combine(constraint)
    }
}

