public enum TarotError {
    case InvalidSeed(String)
    case CardIndexOutOfBounds(UInt8)
    case DuplicateCardDraw(UInt8)
    case SpreadSlotOverflow(requested: UInt64, capacity: UInt64)
    case ConstraintViolation(slotId: UInt8, required: String, actual: String)
    case SpreadNotFound(String)
    case DeserializationError(String)
    case AiProviderUnavailable(String)
    case Unauthorized(String)
    case DeckNotFound(String)
    case OtpArchiveCorrupted(String)
    case OtpManifestMissing
    case OtpManifestInvalid(String)
    case OtpIncompleteDeck(UInt32)
    case InternalLockError
    case IoError(String)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeTarotError: FfiConverterRustBuffer {
    typealias SwiftType = TarotError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TarotError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return try .InvalidSeed(
                FfiConverterString.read(from: &buf)
            )
        case 2: return try .CardIndexOutOfBounds(
                FfiConverterUInt8.read(from: &buf)
            )
        case 3: return try .DuplicateCardDraw(
                FfiConverterUInt8.read(from: &buf)
            )
        case 4: return try .SpreadSlotOverflow(
                requested: FfiConverterUInt64.read(from: &buf),
                capacity: FfiConverterUInt64.read(from: &buf)
            )
        case 5: return try .ConstraintViolation(
                slotId: FfiConverterUInt8.read(from: &buf),
                required: FfiConverterString.read(from: &buf),
                actual: FfiConverterString.read(from: &buf)
            )
        case 6: return try .SpreadNotFound(
                FfiConverterString.read(from: &buf)
            )
        case 7: return try .DeserializationError(
                FfiConverterString.read(from: &buf)
            )
        case 8: return try .AiProviderUnavailable(
                FfiConverterString.read(from: &buf)
            )
        case 9: return try .Unauthorized(
                FfiConverterString.read(from: &buf)
            )
        case 10: return try .DeckNotFound(
                FfiConverterString.read(from: &buf)
            )
        case 11: return try .OtpArchiveCorrupted(
                FfiConverterString.read(from: &buf)
            )
        case 12: return .OtpManifestMissing
        case 13: return try .OtpManifestInvalid(
                FfiConverterString.read(from: &buf)
            )
        case 14: return try .OtpIncompleteDeck(
                FfiConverterUInt32.read(from: &buf)
            )
        case 15: return .InternalLockError
        case 16: return try .IoError(
                FfiConverterString.read(from: &buf)
            )
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TarotError, into buf: inout [UInt8]) {
        switch value {
        case let .InvalidSeed(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)

        case let .CardIndexOutOfBounds(v1):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(v1, into: &buf)

        case let .DuplicateCardDraw(v1):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(v1, into: &buf)

        case let .SpreadSlotOverflow(requested, capacity):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(requested, into: &buf)
            FfiConverterUInt64.write(capacity, into: &buf)

        case let .ConstraintViolation(slotId, required, actual):
            writeInt(&buf, Int32(5))
            FfiConverterUInt8.write(slotId, into: &buf)
            FfiConverterString.write(required, into: &buf)
            FfiConverterString.write(actual, into: &buf)

        case let .SpreadNotFound(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)

        case let .DeserializationError(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)

        case let .AiProviderUnavailable(v1):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(v1, into: &buf)

        case let .Unauthorized(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)

        case let .DeckNotFound(v1):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(v1, into: &buf)

        case let .OtpArchiveCorrupted(v1):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(v1, into: &buf)

        case .OtpManifestMissing:
            writeInt(&buf, Int32(12))

        case let .OtpManifestInvalid(v1):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(v1, into: &buf)

        case let .OtpIncompleteDeck(v1):
            writeInt(&buf, Int32(14))
            FfiConverterUInt32.write(v1, into: &buf)

        case .InternalLockError:
            writeInt(&buf, Int32(15))

        case let .IoError(v1):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(v1, into: &buf)
        }
    }
}

