    return try FfiConverterTypeReadingSession.lift(rustCallWithError(FfiConverterTypeTarotError.lift) {
        uniffi_taroturn_core_fn_func_draw_reading_session(
            FfiConverterString.lower(spreadId),
            FfiConverterOptionString.lower(question),
            FfiConverterOptionString.lower(seedHex),
            FfiConverterFloat.lower(reversalRate), $0
        )
    })
}

